def cv(A, Y):
    P = A @ np.linalg.pinv(A)
    r = A @ fit(A, Y) - Y
    return (np.mean(abs(r / (1 - np.diag(P)).reshape((-1,) + (1,) * (Y.ndim - 1)))), np.sqrt(np.mean(r * r)))

def _groups(study, z):
    (B, C, Q) = [_basis(z, t) @ np.linalg.lstsq(_basis(study[p]['u'], t), study[p][k], rcond=None)[0] for (t, p, k) in [('b', 'panel_b', 'v'), ('c', 'panel_c', 'v1'), ('q', 'panel_c', 'v2')]]
    S = np.sin(2.8 * z)
    A = np.arctan(2.1 * z)
    H = np.cos(1.28 * z) - 1
    fs = [z, S, A, H, B, C, Q]
    G = [np.ones((len(z), len(z)))]
    names = ['1']

    def add(name, f):
        k = f @ f.T
        G.append(k / max(np.mean(np.diag(k)), 1e-10))
        names.append(name)
    for (j, f) in enumerate(fs):
        add(str(j), f)
    for i in range(len(fs)):
        for j in range(i, len(fs)):
            (f, g) = (fs[i], fs[j])
            add(f'{i}{j}', (f[:, :, None] * g[:, None, :]).reshape(len(z), -1))
            if j != i:
                add(f'{i}d{j}', f * g)
    for (j, f) in enumerate([z, B, C, Q, np.column_stack((z, S, A, H))]):
        k = f @ f.T / f.shape[1]
        G.append(k ** 3 / max(np.mean(np.diag(k) ** 3), 1e-10))
        names.append(f'cube{j}')
    return (np.array(G), names)
